## Python Sidecar Engine (`sidecar_engine.py`)

```python
import asyncio
import psutil
import threading
import queue
import time
import signal
import sys
from typing import Optional
from fastapi import FastAPI
from pydantic import BaseModel
import uvicorn
import logging

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class HardwareState(BaseModel):
    ram_usage_percent: float
    vram_usage_percent: Optional[float] = None
    timestamp: float

class BackgroundWorker:
    def __init__(self, task_queue: queue.Queue):
        self.task_queue = task_queue
        self.running = True
        self.worker_thread = threading.Thread(target=self._process_tasks, daemon=True)

    def start(self):
        self.worker_thread.start()
        logger.info("Background worker started")

    def stop(self):
        self.running = False
        # Put a sentinel value to unblock the queue.get() call
        try:
            self.task_queue.put(None, timeout=1)
        except queue.Full:
            pass
        logger.info("Background worker stopping")

    def _process_tasks(self):
        while self.running:
            try:
                task = self.task_queue.get(timeout=1.0)
                if task is None:  # Sentinel to stop processing
                    break

                logger.info(f"Processing task: {task}")
                time.sleep(0.1)  # Simulate work

            except queue.Empty:
                continue
            except Exception as e:
                logger.error(f"Error processing task: {e}")

def get_hardware_state() -> HardwareState:
    """Get current hardware state"""
    ram_percent = psutil.virtual_memory().percent

    # Try to get GPU info (this is simplified - real implementation would need GPU libraries)
    try:
        import GPUtil
        gpus = GPUtil.getGPUs()
        vram_percent = sum(gpu.memoryUtil for gpu in gpus) / len(gpus) if gpus else None
    except ImportError:
        # Fallback if GPUtil is not available
        vram_percent = None

    return HardwareState(
        ram_usage_percent=ram_percent,
        vram_usage_percent=vram_percent,
        timestamp=time.time()
    )

# Global variables for signal handling
app = FastAPI(title="Sidecar Engine", version="1.0.0")
shutdown_event = asyncio.Event()
worker: Optional[BackgroundWorker] = None
task_queue: queue.Queue = queue.Queue(maxsize=100)

@app.get("/api/health")
async def health_check():
    """Health check endpoint returning hardware state"""
    return get_hardware_state()

@app.on_event("startup")
async def startup_event():
    """Initialize background worker on startup"""
    global worker
    logger.info("Starting sidecar engine...")

    # Initialize and start background worker
    worker = BackgroundWorker(task_queue)
    worker.start()

    logger.info("Sidecar engine started successfully")

@app.on_event("shutdown")
async def shutdown_event():
    """Cleanup resources on shutdown"""
    global worker
    logger.info("Shutting down sidecar engine...")

    if worker:
        worker.stop()
        worker.worker_thread.join(timeout=5.0)

    # Signal any waiting operations to stop
    shutdown_event.set()
    logger.info("Sidecar engine shutdown complete")

def signal_handler(signum, frame):
    """Handle termination signals gracefully"""
    sig_name = signal.Signals(signum).name
    logger.info(f"Received {sig_name} signal")

    # Set the shutdown event to interrupt uvicorn
    asyncio.get_event_loop().call_soon_threadsafe(shutdown_event.set)

def run_server(host: str = "127.0.0.1", port: int = 8765):
    """Run the FastAPI server with signal handling"""
    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    logger.info(f"Starting sidecar engine on {host}:{port}")

    try:
        uvicorn.run(
            app,
            host=host,
            port=port,
            log_level="info",
            timeout_keep_alive=30
        )
    except Exception as e:
        logger.error(f"Server error: {e}")
    finally:
        # Ensure cleanup happens even if server fails to start
        if worker:
            worker.stop()
        logger.info("Sidecar engine terminated")

if __name__ == "__main__":
    run_server()
```

## Tauri Client Implementation (Rust) (`src-tauri/src/main.rs`)

```rust
#![cfg_attr(
  all(not(debug_assertions), target_os = "windows"),
  windows_subsystem = "windows"
)]

use std::process::{Command, Stdio};
use std::time::Duration;
use std::thread;
use std::sync::atomic::{AtomicBool, Ordering};
use reqwest::blocking::Client;
use serde::{Deserialize, Serialize};

#[derive(Serialize, Deserialize, Debug)]
struct HardwareState {
    ram_usage_percent: f64,
    vram_usage_percent: Option<f64>,
    timestamp: f64,
}

struct SidecarProcess {
    child: std::process::Child,
    running: AtomicBool,
}

impl SidecarProcess {
    fn new() -> Result<Self, Box<dyn std::error::Error>> {
        let child = Command::new("python3")
            .arg("./sidecar_engine.py")
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()?;

        Ok(SidecarProcess {
            child,
            running: AtomicBool::new(true),
        })
    }

    fn is_running(&self) -> bool {
        self.running.load(Ordering::SeqCst) && self.child.try_wait().map(|x| x.is_none()).unwrap_or(false)
    }

    fn stop(&mut self) -> Result<(), Box<dyn std::error::Error>> {
        self.running.store(false, Ordering::SeqCst);

        // Try graceful shutdown first
        use nix::sys::signal::{kill, Signal};
        let pid = nix::unistd::Pid::from_raw(self.child.id() as i32);
        kill(pid, Signal::SIGTERM).ok();

        // Wait for process to terminate gracefully
        match self.child.wait_timeout(Duration::from_secs(5)) {
            Ok(None) => {
                // Force kill if still running
                use nix::sys::signal::Signal;
                kill(pid, Signal::SIGKILL).ok();
                self.child.wait()?;
            }
            Ok(Some(_)) | Err(_) => {
                let _ = self.child.kill();
            }
        }

        Ok(())
    }
}

fn poll_health_with_backoff(base_url: &str, max_retries: usize) -> Result<HardwareState, Box<dyn std::error::Error>> {
    let client = Client::new();
    let mut delay_ms = 100u64;

    for attempt in 0..max_retries {
        match client.get(&format!("{}/api/health", base_url))
            .timeout(Duration::from_secs(2))
            .send() {
                Ok(response) => {
                    if response.status().is_success() {
                        let state: HardwareState = response.json()?;
                        return Ok(state);
                    }
                },
                Err(_) => {}
            }

        // Exponential backoff with jitter
        let jitter = rand::random::<u64>() % 50;
        thread::sleep(Duration::from_millis(delay_ms + jitter));
        delay_ms = std::cmp::min(delay_ms * 2, 5000); // Cap at 5 seconds
    }

    Err(format!("Failed to connect after {} attempts", max_retries).into())
}

fn main() {
    println!("Starting Tauri application with sidecar engine...");

    let mut sidecar = match SidecarProcess::new() {
        Ok(process) => process,
        Err(e) => {
            eprintln!("Failed to start sidecar process: {}", e);
            std::process::exit(1);
        }
    };

    // Monitor the sidecar process in a separate thread
    let monitor_running = AtomicBool::new(true);
    let monitor_handle = thread::spawn(move || {
        loop {
            if !monitor_running.load(Ordering::SeqCst) {
                break;
            }

            if !sidecar.is_running() {
                eprintln!("Sidecar process has terminated unexpectedly!");
                monitor_running.store(false, Ordering::SeqCst);
                break;
            }

            thread::sleep(Duration::from_secs(1));
        }
    });

    // Poll health endpoint with exponential backoff
    let base_url = "http://127.0.0.1:8765";
    match poll_health_with_backoff(base_url, 10) {
        Ok(state) => println!("Sidecar healthy - RAM: {:.1}%, VRAM: {:?}%", 
                             state.ram_usage_percent, state.vram_usage_percent),
        Err(e) => eprintln!("Failed to get health status: {}", e),
    }

    // Keep application running and monitor sidecar
    println!("Application running. Press Ctrl+C to exit.");

    // Wait for interrupt signal or sidecar termination
    ctrlc::set_handler(|| {
        println!("\nShutting down...");
        let _ = sidecar.stop();
        monitor_running.store(false, Ordering::SeqCst);
        std::process::exit(0);
    }).expect("Error setting Ctrl-C handler");

    // Monitor loop
    while monitor_running.load(Ordering::SeqCst) && sidecar.is_running() {
        thread::sleep(Duration::from_secs(5));

        match poll_health_with_backoff(base_url, 3) {
            Ok(state) => println!("Health check: RAM {:.1}%, timestamp: {}", 
                                 state.ram_usage_percent, state.timestamp),
            Err(e) => eprintln!("Health check failed: {}", e),
        }
    }

    // Cleanup
    let _ = sidecar.stop();
    monitor_running.store(false, Ordering::SeqCst);
}
