## Node.js Client Implementation (`client.js`)

```javascript
const { spawn } = require('child_process');
const http = require('http');
const axios = require('axios');

class SidecarClient {
    constructor(sidecarPath = './sidecar_engine.py', baseUrl = 'http://127.0.0.1:8765') {
        this.sidecarPath = sidecarPath;
        this.baseUrl = baseUrl;
        this.process = null;
        this.isHealthy = false;
    }

    async start() {
        return new Promise((resolve, reject) => {
            console.log('Starting sidecar engine...');

            // Spawn the Python process
            this.process = spawn('python3', [this.sidecarPath], {
                stdio: ['ignore', 'pipe', 'pipe']
            });

            let resolved = false;

            // Handle process events
            this.process.on('error', (err) => {
                if (!resolved) {
                    reject(new Error(`Failed to start sidecar: ${err.message}`));
                    resolved = true;
                }
            });

            this.process.stdout.on('data', (data) => {
                console.log(`Sidecar stdout: ${data}`);
            });

            this.process.stderr.on('data', (data) => {
                console.error(`Sidecar stderr: ${data}`);
            });

            this.process.on('close', (code, signal) => {
                if (!resolved) {
                    const message = signal ? 
                        `Sidecar terminated with signal: ${signal}` : 
                        `Sidecar exited with code: ${code}`;
                    console.error(message);

                    // Try to restart on unexpected termination
                    if (this.shouldRestart()) {
                        console.log('Attempting to restart sidecar...');
                        setTimeout(() => this.start().then(resolve), 1000);
                    } else {
                        reject(new Error(message));
                    }
                }
            });

            // Wait for health check with exponential backoff
            this.pollHealthWithBackoff()
                .then(() => {
                    console.log('Sidecar started successfully');
                    resolve();
                })
                .catch((err) => {
                    if (!resolved) {
                        reject(err);
                    }
                });
        });
    }

    async pollHealthWithBackoff(maxRetries = 10, initialDelayMs = 100) {
        let delayMs = initialDelayMs;

        for (let attempt = 0; attempt < maxRetries; attempt++) {
            try {
                const response = await axios.get(`${this.baseUrl}/api/health`, {
                    timeout: 2000
                });

                if (response.status === 200) {
                    this.isHealthy = true;
                    console.log('Sidecar health check successful:', response.data);
                    return response.data;
                }
            } catch (error) {
                // Log retry attempts for debugging
                if (attempt < maxRetries - 1) {
                    const jitter = Math.random() * 50;
                    await this.sleep(delayMs + jitter);
                    delayMs = Math.min(delayMs * 2, 5000); // Cap at 5 seconds
                }
            }
        }

        throw new Error(`Failed to connect after ${maxRetries} attempts`);
    }

    async stop() {
        if (this.process) {
            console.log('Stopping sidecar engine...');

            // Send SIGTERM for graceful shutdown
            this.process.kill('SIGTERM');

            // Wait a bit then force kill if needed
            await new Promise(resolve => setTimeout(resolve, 5000));

            if (!this.process.killed) {
                console.log('Force killing sidecar...');
                this.process.kill('SIGKILL');
            }

            this.isHealthy = false;
        }
    }

    sleep(ms) {
        return new Promise(resolve => setTimeout(resolve, ms));
    }

    shouldRestart() {
        // Implement logic to determine if restart is appropriate
        // For example, don't restart if the process exited cleanly
        return true;
    }

    getHealth() {
        return this.isHealthy;
    }
}

// Setup signal handlers for graceful shutdown
process.on('SIGINT', () => {
    console.log('\nReceived SIGINT, shutting down...');
    client.stop().then(() => process.exit(0));
});

process.on('SIGTERM', () => {
    console.log('Received SIGTERM, shutting down...');
    client.stop().then(() => process.exit(0));
});

// Main execution
async function main() {
    const client = new SidecarClient();

    try {
        await client.start();

        // Periodic health checks
        setInterval(async () => {
            if (client.getHealth()) {
                try {
                    const health = await axios.get('http://127.0.0.1:8765/api/health');
                    console.log(`Periodic health check:`, health.data);
                } catch (error) {
                    console.error('Periodic health check failed:', error.message);
                }
            } else {
                console.log('Sidecar not healthy, attempting restart...');
                await client.start();
            }
        }, 30000); // Every 30 seconds

    } catch (error) {
        console.error('Failed to start sidecar:', error.message);
        process.exit(1);
    }
}

// Run the client
const client = new SidecarClient();
main().catch(console.error);

module.exports = { SidecarClient };
